import { useRef } from 'react'
import { GestureResponderEvent, Animated, Pressable } from 'react-native'
import { MotiView } from 'moti'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils'
import { Image } from 'expo-image'

interface FabButtonProps {
	visible: boolean
	onPress: () => void
	onPressIn?: (event: GestureResponderEvent) => void
	onPressOut?: (event: GestureResponderEvent) => void
}

export const FabButton = ({
	visible,
	onPress,
	onPressIn,
	onPressOut
}: FabButtonProps) => {
	const { theme } = useTheme()
	const animatedValue = useRef(new Animated.Value(1)).current

	const handlePressIn = (event: GestureResponderEvent) => {
		if (onPressIn) onPressIn(event)
		Animated.timing(animatedValue, {
			toValue: 0.8,
			duration: 200,
			useNativeDriver: true
		}).start()
	}

	const handlePressOut = (event: GestureResponderEvent) => {
		if (onPressOut) onPressOut(event)

		Animated.timing(animatedValue, {
			toValue: 1,
			duration: 200,
			useNativeDriver: true
		}).start()
	}

	const pressInStyle = { transform: [{ scaleY: animatedValue }] }

	return (
		<MotiView
			from={{ opacity: 0 }}
			animate={{ opacity: visible ? 1 : 0 }}
			transition={{ type: 'timing', duration: 300 }}
			style={styles.fabContainer}
		>
			<Pressable
				onPress={onPress}
				onPressIn={handlePressIn}
				onPressOut={handlePressOut}
			>
				<Animated.View style={[styles.fab(theme), pressInStyle]}>
					<Image
						source={'logo.png'}
						style={{ width: 20, height: 20, marginRight: 6 }}
						contentFit="contain"
						tintColor={colors[theme].gray[900]}
					/>
				</Animated.View>
			</Pressable>
		</MotiView>
	)
}

const styles = defineStyles({
	fabContainer: {
		position: 'absolute',
		bottom: 100,
		left: 0
	},
	fab: (theme: Theme) => ({
		width: 40,
		height: 40,
		borderTopRightRadius: 25,
		borderBottomRightRadius: 25,
		backgroundColor: colors[theme].background,
		justifyContent: 'center',
		alignItems: 'center',
		borderRightWidth: 1,
		borderTopWidth: 1,
		borderBottomWidth: 1,
		borderColor: colors[theme].gray[75],
		elevation: 5
	})
})
